public static class WindingTests94 {
 static List<(UnityEngine.Vector2,UnityEngine.Vector2)> Edges(float[] p){var e=new List<(UnityEngine.Vector2,UnityEngine.Vector2)>();for(int i=0;i<p.Length;i+=6){var a=new UnityEngine.Vector2(p[i],p[i+1]);var b=new UnityEngine.Vector2(p[i+2],p[i+3]);var c=new UnityEngine.Vector2(p[i+4],p[i+5]);double area=(double)(b.x-a.x)*(c.y-a.y)-(double)(b.y-a.y)*(c.x-a.x);if(area<0)(b,c)=(c,b);e.Add((a,b));e.Add((b,c));e.Add((c,a));}return e;}
 static void Save(string path,List<(UnityEngine.Vector2,UnityEngine.Vector2)> e){using(var b=new BinaryWriter(new FileStream(path,FileMode.CreateNew))){b.Write(e.Count);foreach(var p in e){b.Write(p.Item1.x);b.Write(p.Item1.y);b.Write(p.Item2.x);b.Write(p.Item2.y);}}}
 static List<(UnityEngine.Vector2,UnityEngine.Vector2)> Input(string path){using(var b=new BinaryReader(File.OpenRead(path))){if(b.ReadString()!="union-input94/v1")throw new Exception("input ABI");string source=b.ReadString();int frame=b.ReadInt32();int n=b.ReadInt32();b.BaseStream.Seek(n*8L,SeekOrigin.Current);n=b.ReadInt32();b.BaseStream.Seek(n*4L,SeekOrigin.Current);n=b.ReadInt32();b.BaseStream.Seek(n*24L,SeekOrigin.Current);n=b.ReadInt32();b.BaseStream.Seek(n*13L,SeekOrigin.Current);n=b.ReadInt32();if(n<1||n>65536)throw new Exception("segment count");var e=new List<(UnityEngine.Vector2,UnityEngine.Vector2)>();for(int i=0;i<n;i++)e.Add((new UnityEngine.Vector2(b.ReadSingle(),b.ReadSingle()),new UnityEngine.Vector2(b.ReadSingle(),b.ReadSingle())));if(b.BaseStream.Position!=b.BaseStream.Length)throw new Exception("trailing input");Console.WriteLine("INPUT "+source+" frame="+frame+" segments="+n);return e;}}
 static int Main(string[] args){if(args.Length>1){var e=Input(args[1]);foreach(bool spatial in new[]{false,true}){ClosedRegion524.UseSpatialIndex526=spatial;try{var q=ClosedRegion524.BuildSegments(e);Console.WriteLine("INPUT_PASS spatial="+spatial+" loops="+q.Count);}catch(Exception ex){Console.WriteLine("INPUT_FAIL spatial="+spatial+" "+ex.Message);}}return 0;}int tests=0;var random=new Random(94);for(int j=0;j<256;j++){int n=1+j%8;var p=new float[n*6];for(int i=0;i<n;i++){float x=220+(float)random.NextDouble()*10,y=120+(float)random.NextDouble()*10;for(int k=0;k<3;k++){p[i*6+k*2]=x+(float)random.NextDouble()*3;p[i*6+k*2+1]=y+(float)random.NextDouble()*3;}}var e=Edges(p);foreach(bool spatial in new[]{false,true}){ClosedRegion524.UseSpatialIndex526=spatial;try{var q=ClosedRegion524.BuildSegments(e);tests++;}catch(Exception ex){Save(Path.Combine(args[0],"FAIL94-"+j+"-"+spatial+".bin"),e);Console.WriteLine("FAIL "+j+" "+spatial+" "+ex);return 2;}}}Console.WriteLine("PASS "+tests+" coherent oriented random unions; engine-free Vector2 arithmetic stub, not actual gameplay reproduction");return 0;}
